import{_ as i,a0 as l,w as p,s as h,ao as r,I as o,x as t,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Antergos：基於 Arch 發行版，想要嘗試 Arch 的絕對值得一試 | LCTT x X-CMD","titleTemplate":false,"description":"Antergos：基於 Arch 發行版，想要嘗試 Arch 的絕對值得一試 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Antergos：基於 Arch 發行版，想要嘗試 Arch 的絕對值得一試 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Antergos：基於 Arch 發行版，想要嘗試 Arch 的絕對值得一試 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20161010 Antergos – Best Arch based distro for beginners","title":"Antergos：基於 Arch 發行版，想要嘗試 Arch 的絕對值得一試","tag":"201610","desc":""},"relativePath":"201610/20161010 Antergos – Best Arch based distro for beginners.md","filePath":"[post].md"}'),d={name:"201610/20161010 Antergos – Best Arch based distro for beginners.md"};function g(m,e,c,w,u,x){const a=l("Link");return p(),h("div",null,[e[16]||(e[16]=r('<h1 id="antergos-基於-arch-發行版-想要嘗試-arch-的絕對值得一試" tabindex="-1">Antergos：基於 Arch 發行版，想要嘗試 Arch 的絕對值得一試 <a class="header-anchor" href="#antergos-基於-arch-發行版-想要嘗試-arch-的絕對值得一試" aria-label="Permalink to “Antergos：基於 Arch 發行版，想要嘗試 Arch 的絕對值得一試”">​</a></h1><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>眾所周知，Arch Linux 是最好的 Linux 發行版之一，我們可以隨心所欲的進行定製。我們可以滾動式更新最新的軟件，但它的安裝和配置的過程對於初學者則相對困難。現在就讓我來為你展示如何安裝 Antergos，這個基於 Arch 的、給新手的最好發行版，要嘗試 Arch 的用户可以試一試，我保證絕對值得一試。</p><p>Antergos 是一個滾動式更新的發行版，基於 Arch Linux 提供桌面環境，是集現代化、高雅和高效率於一體的操作系統。想要挑戰一下安裝 Arch Linux 的用户，都可以先試一試 Antergos。</p><p>由於是滾動式更新，當上遊發佈更新，你的整個系統 (包括系統組件和你已安裝的應用) 就會升級到最新的滾動版本，僅僅稍微延期一點時間以確保系統的穩定。</p><p>Antergos 有多個語言版本，包括英語、西班牙語等版本，在安裝時你可以在語言欄選擇預置語言。默認的配置確保了開箱即用，不需要安裝額外的軟件就可以直接瀏覽網頁、聽音樂、看視頻以及做任何你想做的事情。</p><p>Antergos 項目最初名字是 Cinnarch，並且只提供一個桌面環境。現在它有多個桌面環境（包括 Cinnamon、Gnome、KDE、MATE、Openbox 和 Xfce）以供用户在安裝之時進行選擇。同時，它還默認包含了著名的 Numix GTK 主題和 Icon 主題。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><h4 id="下載-antergos-linux" tabindex="-1">下載 Antergos Linux <a class="header-anchor" href="#下載-antergos-linux" aria-label="Permalink to “下載 Antergos Linux”">​</a></h4>',9)),o("p",null,[e[1]||(e[1]=t("訪問 ",-1)),n(a,{href:"https://antergos.com/try-it/"},{default:s(()=>[...e[0]||(e[0]=[t("Antergos",-1)])]),_:1}),e[2]||(e[2]=t(" 下載頁面，然後下載最新的 Live ISO 鏡像。任何人都可以免費獲取 Antergos 鏡像，燒錄到 CD/DVD 或者寫到 USB 設備，開始 Antergos 之旅。",-1))]),e[17]||(e[17]=r('<h4 id="創建可啓動-usb" tabindex="-1">創建可啓動 USB <a class="header-anchor" href="#創建可啓動-usb" aria-label="Permalink to “創建可啓動 USB”">​</a></h4><p>下載好最新的 Antergos Live ISO 鏡像之後，你需要使用命令列或者圖形界面的方法來製作一個可啓動介質。</p><h4 id="使用-antergos-安裝介質來啓動電腦" tabindex="-1">使用 Antergos 安裝介質來啓動電腦 <a class="header-anchor" href="#使用-antergos-安裝介質來啓動電腦" aria-label="Permalink to “使用 Antergos 安裝介質來啓動電腦”">​</a></h4><p>使用 Antergos 安裝介質來啓動電腦。成功啓動到 Live ISO 之後，你會看到與下圖相似的界面。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-1.png" alt=""></p><p>點擊 Install It 按鈕開始 Angergos 的安裝過程。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-2.png" alt=""></p><h4 id="選擇語系" tabindex="-1">選擇語系 <a class="header-anchor" href="#選擇語系" aria-label="Permalink to “選擇語系”">​</a></h4><p>Antergos 的易於使用的圖形安裝器非常不錯。此處選擇你需要選用的語系並點擊 Next 按鈕繼續下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-3.png" alt=""></p><h4 id="系統檢測" tabindex="-1">系統檢測 <a class="header-anchor" href="#系統檢測" aria-label="Permalink to “系統檢測”">​</a></h4><p>請確保你有足夠的磁盤空間，連接好電源以及連接到網絡，點擊 Next 按鈕繼續下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-4.png" alt=""></p><h4 id="選擇地點" tabindex="-1">選擇地點 <a class="header-anchor" href="#選擇地點" aria-label="Permalink to “選擇地點”">​</a></h4><p>選擇地點可以幫助決定系統所使用的本地化信息（locale）。通常是選擇你所屬的國家即可。這裏有一個基於你選擇的語言的位置的簡短列表。點擊 Next 按鈕繼續下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-5.png" alt=""></p><h4 id="選擇時區" tabindex="-1">選擇時區 <a class="header-anchor" href="#選擇時區" aria-label="Permalink to “選擇時區”">​</a></h4><p>選擇使用的時區，然後點擊 Next 按鈕繼續下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-6.png" alt=""></p><h4 id="選擇鍵盤佈局" tabindex="-1">選擇鍵盤佈局 <a class="header-anchor" href="#選擇鍵盤佈局" aria-label="Permalink to “選擇鍵盤佈局”">​</a></h4><p>選擇你選用的鍵盤佈局，然後點擊 Next 按鈕繼續下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-7.png" alt=""></p><h4 id="選擇桌面環境" tabindex="-1">選擇桌面環境 <a class="header-anchor" href="#選擇桌面環境" aria-label="Permalink to “選擇桌面環境”">​</a></h4><p>Antergos 提供了多個選擇（包括 Cinnamon、Gnome、KDE、MATE、Openbox 和 Xfce），根據你的喜好進行選擇即可。然後點擊 Next 按鈕繼續下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-8.png" alt=""></p><h4 id="gnome-–-特性選擇" tabindex="-1">Gnome – 特性選擇 <a class="header-anchor" href="#gnome-–-特性選擇" aria-label="Permalink to “Gnome – 特性選擇”">​</a></h4><p>這裏我選擇了默認的 Gnome 桌面環境，此處你可以選擇需要額外安裝的軟件以及正確的驅動程序。然後點擊 Next 按鈕繼續下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-10.png" alt=""></p><h4 id="安裝類型" tabindex="-1">安裝類型 <a class="header-anchor" href="#安裝類型" aria-label="Permalink to “安裝類型”">​</a></h4><p>初次安裝可以選擇第一個選項（ Erase disk and install Antergos ）。然後點擊 Next 按鈕繼續下一步。（LCTT 譯註，但是要注意這個選項會擦除你的整個硬盤數據，如果你是全新安裝，則可以使用該選項。）</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-11.png" alt=""></p><h4 id="自動安裝模式" tabindex="-1">自動安裝模式 <a class="header-anchor" href="#自動安裝模式" aria-label="Permalink to “自動安裝模式”">​</a></h4><p>這裏會有一個檫除硬盤的警告，並選擇安裝 Grub 啓動器，然後點擊 Next 按鈕繼續下一步。</p><blockquote><p>WARNING ! This will overwrite everything currently on your drive !</p></blockquote><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-12.png" alt=""></p><h4 id="安裝設置綜述" tabindex="-1">安裝設置綜述 <a class="header-anchor" href="#安裝設置綜述" aria-label="Permalink to “安裝設置綜述”">​</a></h4><p>確認最後的安裝設置概覽，如地點、時區、鍵盤佈局、桌面環境和特性，然後點擊 Next 按鈕繼續下一步。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-14.png" alt=""></p><h4 id="創建你的用户名" tabindex="-1">創建你的用户名 <a class="header-anchor" href="#創建你的用户名" aria-label="Permalink to “創建你的用户名”">​</a></h4><p>此時需要為你的系統創建一個新用户名和對應的密碼，然後點擊 Next 按鈕繼續下一步。</p><ul><li>你的暱稱</li><li>電腦名稱</li><li>用户名</li><li>設置密碼</li><li>密碼二次確認</li><li>選擇“登錄系統需要密碼”</li></ul><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-15.png" alt=""></p><h4 id="安裝進程" tabindex="-1">安裝進程 <a class="header-anchor" href="#安裝進程" aria-label="Permalink to “安裝進程”">​</a></h4><p>此時就是等待 Antergos 安裝完成。安裝好之後，移除安裝介質在點擊“立刻重啓”按鈕。</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-16.png" alt=""></p><h4 id="輸入用户名和密碼" tabindex="-1">輸入用户名和密碼 <a class="header-anchor" href="#輸入用户名和密碼" aria-label="Permalink to “輸入用户名和密碼”">​</a></h4><p>這是歡迎界面，輸入密碼即可登錄：</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-17.png" alt=""></p><p>發行信息截圖：</p><p><img src="http://www.2daygeek.com/wp-content/uploads/2016/08/antergos-linux-gnome-desktop-installation-steps-with-screenshots-18.png" alt=""></p><p>我們還會提供了一些列循序漸進的 Linux 系統管理的相關文章。如果本文對你有用，請花費幾分鐘分享你得想法到評論區。</p><p>請於我們保持聯繫，祝君好運！</p><hr>',53)),o("p",null,[e[4]||(e[4]=t("via: ",-1)),n(a,{href:"http://www.2daygeek.com/how-to-install-antergos-linux/"},{default:s(()=>[...e[3]||(e[3]=[t("http://www.2daygeek.com/how-to-install-antergos-linux/",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("作者：",-1)),n(a,{href:"http://www.2daygeek.com/author/magesh/"},{default:s(()=>[...e[5]||(e[5]=[t("MAGESH MARUTHAMUTHU",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),n(a,{href:"https://github.com/GHLandy"},{default:s(()=>[...e[6]||(e[6]=[t("GHLandy",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[13]||(e[13]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const f=i(d,[["render",g]]);export{b as __pageData,f as default};
